-- Function: public.fn_get_events_by_branch
-- Backup generated on 2026-10-25 20:33:18

CREATE OR REPLACE FUNCTION public.fn_get_events_by_branch(p_tenant_id uuid, p_branch_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, title character varying, description text, event_type_id uuid, event_date date, start_time time without time zone, end_time time without time zone, location character varying, organizer_id uuid, status character varying, scope character varying, branch_id uuid, is_organization_wide boolean, photo_urls text[], created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT DISTINCT ev.id, ev.tenant_id, ev.title, ev.description, ev.event_type_id,            ev.event_date, ev.start_time, ev.end_time, ev.location, ev.organizer_id,            ev.status, ev.scope, ev.branch_id, ev.is_organization_wide,            ev.photo_urls, ev.created_at, ev.updated_at     FROM events ev     LEFT JOIN event_classrooms ec ON ev.id = ec.event_id     LEFT JOIN classrooms c ON c.id = ec.classroom_id     WHERE ev.tenant_id = p_tenant_id        AND (ev.scope = 'Organization'             OR ev.is_organization_wide = true             OR (ev.scope = 'Branch' AND ev.branch_id = p_branch_id)            OR (c.branch_id = p_branch_id))     ORDER BY ev.event_date DESC, ev.start_time ASC NULLS LAST; END; $function$ ;
